const ANGLES=[["Quel regard portez-vous sur {s} dans votre équipe ?","Comment évaluez-vous la situation concernant {s} ?","Que révèle, selon vous, le dossier {s} ?"],["Certains vous reprochent votre gestion de {s}. Que répondez-vous ?","Assumez-vous personnellement les choix autour de {s} ?","Pourquoi votre méthode concernant {s} suscite-t-elle des critiques ?"],["Comment votre groupe réagit-il à {s} ?","Quelles discussions avez-vous eues au vestiaire à propos de {s} ?","Les joueurs partagent-ils votre analyse de {s} ?"],["Quelle décision concrète prendrez-vous maintenant sur {s} ?","Quels changements envisagez-vous au sujet de {s} ?","Comment comptez-vous faire évoluer {s} lors des prochaines semaines ?"]];
