function validate(){if(TOPICS.length!==25||questions.length!==500||new Set(questions.map(q=>q.id)).size!==500||questions.some(q=>q.variants.length!==3||new Set(q.variants).size!==3||q.answers.length!==4||new Set(q.answers.map(a=>a.text)).size!==4))throw Error('Banque V60 invalide');return true;}
function recent(history,q,season,week){return history.some(h=>h.id===q.id&&((season-h.season)*30+week-h.week)>=0&&((season-h.season)*30+week-h.week)<12);}
